package com.franco.desco.adapter.in.web.visit;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.visit.*;import com.franco.desco.application.visit.port.in.VisitUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController@RequestMapping("/api/v1/visitas")@Tag(name="Visitas técnicas",description="Inicio, seguimiento, finalización y evidencias de visitas técnicas.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class VisitController{private final VisitUseCase u;private final VisitWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public VisitController(VisitUseCase u,VisitWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_LISTAR')")@Operation(operationId="visitasListar",summary="Listar visitas técnicas")public ResponseEntity<ApiResponse<PageResponse<VisitResponses.Summary>>>list(@RequestParam(required=false)Long predioId,@RequestParam(required=false)Long empleadoId,@RequestParam(required=false)Long salidaCampoId,@RequestParam(required=false)String estadoProceso,@RequestParam(required=false)Instant fechaDesde,@RequestParam(required=false)Instant fechaHasta,@RequestParam(required=false)String buscar,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(200)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,predioId,empleadoId,salidaCampoId,estadoProceso,fechaDesde,fechaHasta,buscar),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_VER')")@Operation(operationId="visitasVer",summary="Ver detalle de visita")public ResponseEntity<ApiResponse<VisitResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new VisitCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping("/iniciar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_EDITAR')")@Operation(operationId="visitasIniciar",summary="Iniciar visita técnica",description="El PA puede iniciar automáticamente la salida relacionada cuando corresponda.")public ResponseEntity<ApiResponse<VisitResponses.Created>>start(@Valid@RequestBody VisitRequests.Start q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.start(new VisitCommands.Start(q.salidaParticipanteId(),q.predioId(),q.fechaHoraInicio(),q.latitud(),q.longitud(),q.objetivo()),ids.resolve(a),meta.resolve(r)),r,VisitResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_EDITAR')")@Operation(operationId="visitasEditar",summary="Editar visita")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody VisitRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new VisitCommands.Update(id,q.objetivo(),q.resumen(),q.recomendaciones()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/finalizar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_CONFIRMAR')")@Operation(operationId="visitasFinalizar",summary="Finalizar visita")public ResponseEntity<ApiResponse<Void>>finish(@PathVariable Long id,@Valid@RequestBody VisitRequests.Finish q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.finish(new VisitCommands.Finish(id,q.fechaHoraFin(),q.resumen(),q.recomendaciones()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/anular")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'VISITAS_RETIRAR')")@Operation(operationId="visitasAnular",summary="Anular visita")public ResponseEntity<ApiResponse<Void>>annul(@PathVariable Long id,@Valid@RequestBody VisitRequests.Annul q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.annul(new VisitCommands.Annul(id,q.motivo(),q.fechaHoraFin()),ids.resolve(a),meta.resolve(r)),r);}}
